import * as THREE from './vendor/three.module.js';
const croppedSides=new WeakMap(),rearMaps=new WeakMap();
export const OCTAVIA_COLORS={blue:'#1764ae',red:'#a61725',white:'#e8e8e4',grey:'#666b70',black:'#111418'};
// A 4.70 m estate silhouette with textured rear, real side proportions and separate moving wheels.
export function createOctavia({rear,side,paint='blue'}={}){
 const group=new THREE.Group();group.name='Octavia · carrocería continua y detalles';
 const body=new THREE.MeshPhysicalMaterial({color:OCTAVIA_COLORS[paint]||OCTAVIA_COLORS.blue,metalness:.55,roughness:.27,clearcoat:.9,clearcoatRoughness:.16});
 const glass=new THREE.MeshPhysicalMaterial({color:'#202d36',metalness:.35,roughness:.17,clearcoat:1});
 const black=new THREE.MeshStandardMaterial({color:'#15181b',roughness:.66}),chrome=new THREE.MeshStandardMaterial({color:'#aeb4bb',metalness:.92,roughness:.24}),red=new THREE.MeshStandardMaterial({color:'#b81f2a',roughness:.4}),lamp=new THREE.MeshStandardMaterial({color:'#d31525',emissive:'#db1325',emissiveIntensity:.7,roughness:.25});
 function mesh(geo,mat=body,parent=group){const m=new THREE.Mesh(geo,mat);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
 function box(x,y,z,w,h,d,mat){const m=mesh(new THREE.BoxGeometry(w,h,d),mat);m.position.set(x,y,z);return m;}
 function shell(rings,material){const positions=[],uv=[],indices=[],profile=[[-.80,0],[.80,0],[1,.24],[1,.68],[.85,1],[-.85,1],[-1,.68],[-1,.24]];for(const [i,[z,w,b,t]]of rings.entries())for(const [j,[x,y]]of profile.entries()){positions.push(x*w,b+y*(t-b),z);uv.push(j/8,i/(rings.length-1));}for(let i=0;i<rings.length-1;i++)for(let j=0;j<8;j++){const a=i*8+j,b=i*8+(j+1)%8;indices.push(a,b,a+8,b,b+8,a+8);}indices.push(0,2,1,0,3,2,0,4,3,0,5,4,0,6,5,0,7,6);const last=(rings.length-1)*8;for(let j=1;j<7;j++)indices.push(last,last+j,last+j+1);const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));g.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));g.setIndex(indices);g.computeVertexNormals();return mesh(g,material);}
 shell([[-2.35,.78,.3,.65],[-2.08,.88,.26,.79],[-1.35,.915,.28,.88],[.75,.915,.29,.94],[1.85,.9,.3,.98],[2.35,.81,.38,.85]],body);
 shell([[-1.25,.76,.84,.86],[-.62,.72,.86,1.39],[.95,.72,.91,1.46],[1.75,.73,.94,1.36],[2.12,.77,.92,1.04]],glass);
 // Roof and pillars preserve the estate profile instead of a floating rectangular cabin.
 shell([[-.65,.735,1.35,1.41],[.95,.735,1.42,1.47],[1.7,.70,1.34,1.39]],body);
 for(const s of [-1,1]){box(s*.735,1.05,.18,.045,.68,.07,black);const pillar=box(s*.735,1.13,1.65,.055,.55,.06,body);pillar.rotation.x=.28;box(s*.63,1.49,.55,.025,.025,1.85,black);box(s*.95,.98,-.78,.20,.12,.27,body);box(s*.78,.84,2.31,.25,.12,.035,lamp);box(s*.6,.67,-2.28,.42,.065,.03,chrome);box(s*.75,.34,2.30,.30,.12,.12,chrome);box(s*.916,.71,.6,.013,.025,.22,chrome);box(s*.916,.71,-.65,.013,.025,.22,chrome);}
 box(0,.37,2.30,1.5,.15,.12,black);box(0,.5,-2.31,1.35,.25,.035,black);for(let x=-.55;x<.6;x+=.09)box(x,.52,-2.34,.018,.21,.025,chrome);box(0,1.4,1.95,1.5,.045,.22,black);
 const wheels=[];for(const s of [-1,1])for(const z of [-1.43,1.32]){const wheel=new THREE.Group();wheel.position.set(s*.87,.335,z);group.add(wheel);const tyre=mesh(new THREE.CylinderGeometry(.335,.335,.23,24),black,wheel);tyre.rotation.z=Math.PI/2;const disc=mesh(new THREE.CylinderGeometry(.245,.245,.235,24),chrome,wheel);disc.rotation.z=Math.PI/2;for(let k=0;k<5;k++){const spoke=mesh(new THREE.BoxGeometry(.25,.035,.47),chrome,wheel);spoke.rotation.x=k*Math.PI/5;}const cap=mesh(new THREE.CylinderGeometry(.065,.065,.25,16),black,wheel);cap.rotation.z=Math.PI/2;box(s*.88,.37,z+.16,.22,.20,.09,red);wheels.push({mesh:wheel,z});}
 if(rear){let map=rearMaps.get(rear);if(!map){map=new THREE.Texture(rear.image);map.colorSpace=THREE.SRGBColorSpace;map.anisotropy=rear.anisotropy;map.offset.set(.025,.045);map.repeat.set(.72,.82);map.needsUpdate=true;rearMaps.set(rear,map);}const m=mesh(new THREE.PlaneGeometry(1.96,1.48),new THREE.MeshBasicMaterial({map,transparent:true,alphaTest:.12}));m.position.set(0,.78,2.37);m.castShadow=false;}

 // The side image already has an alpha cutout. Only the body area is used; 3D wheels remain free to rotate.
 if(side){const aspect=side.userData.vehicleAspect||2.7;for(const s of [-1,1]){let maps=croppedSides.get(side);if(!maps){maps=new Map();croppedSides.set(side,maps);}let texture=maps.get(s);if(!texture){texture=new THREE.Texture(side.image);texture.colorSpace=THREE.SRGBColorSpace;texture.anisotropy=side.anisotropy;texture.offset.copy(side.offset);texture.repeat.copy(side.repeat);texture.offset.y+=texture.repeat.y*.34;texture.repeat.y*=.66;if(s<0){texture.offset.x+=texture.repeat.x;texture.repeat.x*=-1;}texture.needsUpdate=true;maps.set(s,texture);}const plane=mesh(new THREE.PlaneGeometry(4.7,4.7/aspect*.66),new THREE.MeshBasicMaterial({map:texture,transparent:true,alphaTest:.3}));plane.position.set(s*.926,4.7/aspect*.67+.02,0);plane.rotation.y=s*Math.PI/2;plane.castShadow=false;}}
 // Batch the stationary body panels; wheels retain independent transforms.
 group.updateMatrixWorld(true);const batches=new Map();group.traverse(item=>{if(!item.isMesh||item.material.transparent||item.parent!==group)return;const key=item.material.uuid;if(!batches.has(key))batches.set(key,[]);batches.get(key).push(item);});for(const parts of batches.values()){if(parts.length<2)continue;const positions=[],normals=[],uv=[],indices=[];let offset=0;for(const item of parts){const g=item.geometry.clone().applyMatrix4(item.matrixWorld),p=g.getAttribute('position');positions.push(...p.array);normals.push(...g.getAttribute('normal').array);uv.push(...g.getAttribute('uv').array);const ix=g.getIndex();for(const value of ix?ix.array:Array.from({length:p.count},(_,i)=>i))indices.push(value+offset);offset+=p.count;g.dispose();group.remove(item);item.geometry.dispose();}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));g.setAttribute('normal',new THREE.Float32BufferAttribute(normals,3));g.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));g.setIndex(indices);mesh(g,parts[0].material);}
 group.userData.disposeMaterials=()=>{const materials=new Set();group.traverse(item=>{if(item.material)materials.add(item.material);});for(const material of materials)material.dispose();};group.userData.wheels=wheels;group.userData.length=4.7;group.userData.model='octavia';return group;
}
export function rollVehicle(group,distance,steering=0){for(const wheel of group.userData.wheels||[]){wheel.mesh.rotation.x=distance/.335;wheel.mesh.rotation.y=wheel.z<0?-steering*.35:0;}}

export function releaseVehicleMaps(source){const rear=rearMaps.get(source);rear?.dispose();rearMaps.delete(source);const sides=croppedSides.get(source);if(sides)for(const texture of sides.values())texture.dispose();croppedSides.delete(source);}
